// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(this)); // owner is the setUp deployer (this test contract)
        vm.prank(actor);
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }
        // Rule: a non-owner caller can NEVER successfully destroy the contract.
        assertTrue(!ok, "non-owner must not be able to selfdestruct");
    }
}
